//! SD-26 Epic 3, Criterion 3.4 — verifies the on-disk Bestiary 1 JSON
//! cache at `data/corpus/beastiary/{monster,equipment}/*.json`,
//! generated by `codex::rules_core::cache_gen::beastiary1::generate()`
//! (see `src/bin/gen_cache_beastiary.rs`). Reads only the
//! already-generated files — this test does not require a live PCGen
//! corpus checkout, matching the acceptance command `cargo test --locked
//! --test sd26_cache_beastiary` (`acceptance-and-verification.md` row
//! 3.4).
//!
//! Real, MEASURED ceilings this test asserts against (independently
//! re-verified this cycle directly against the live corpus checkout —
//! `decisions.md §11.4`): monsters 41/41 (`MonsterId::ALL`, the
//! corrected roster across subsets 01–08); equipment `description`
//! 4/4 (100%) — the real record count is **4**, not the ~7 a prior
//! SD-25 estimate assumed (`decisions.md §11.4`'s own correction note,
//! independently re-confirmed this cycle by direct grep of the live
//! `b1_equip_{general,arms_armor,magic_items}.lst` files).

use std::collections::{BTreeSet, HashSet};
use std::fs;
use std::path::{Path, PathBuf};

use serde_json::Value;

use codex::rules_core::rules_tables::RuleSetId;
use codex::rules_core::rules_tables::beastiary1::monster_key_resolve;

fn repo_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn cache_dir() -> PathBuf {
    repo_root().join("data/corpus/beastiary")
}

fn load_all(kind: &str) -> Vec<(PathBuf, Value)> {
    let dir = cache_dir().join(kind);
    let mut out = Vec::new();
    for entry in fs::read_dir(&dir).unwrap_or_else(|e| panic!("read_dir {}: {e}", dir.display())) {
        let path = entry.unwrap().path();
        if path.extension().map(|e| e == "json").unwrap_or(false) {
            let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
            let value: Value =
                serde_json::from_str(&text).unwrap_or_else(|e| panic!("invalid JSON in {}: {e}", path.display()));
            out.push((path, value));
        }
    }
    out
}

const ALLOWED_SOURCE_KINDS: &[&str] = &[
    "lst_token",
    "lst_inherited_copy",
    "lst_corrected_ingest",
    "web_second_source",
    "same_book_fallback",
];

fn assert_shape_b_record(path: &Path, record: &Value) {
    let obj = record.as_object().unwrap_or_else(|| panic!("{}: not a JSON object", path.display()));

    let population = obj.get("population").and_then(Value::as_str);
    assert_eq!(
        population,
        Some("in_scope"),
        "{}: population must be in_scope (Bestiary 1 is a real, shipped book)",
        path.display()
    );

    let completeness = obj.get("completeness").and_then(Value::as_str);
    assert!(
        matches!(completeness, Some("chassis_only") | Some("full")),
        "{}: completeness must be chassis_only or full, got {completeness:?}",
        path.display()
    );

    let ingested_at = obj
        .get("ingested_at")
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{}: missing ingested_at", path.display()));
    assert!(
        ingested_at.contains('T') && (ingested_at.ends_with('Z') || ingested_at.contains('+') || ingested_at.contains('-')),
        "{}: ingested_at {ingested_at:?} is not ISO-8601-shaped",
        path.display()
    );

    assert!(obj.contains_key("data"), "{}: missing data", path.display());

    let source = obj
        .get("source")
        .and_then(Value::as_object)
        .unwrap_or_else(|| panic!("{}: missing source object", path.display()));
    let kind = source
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{}: source missing kind", path.display()));
    assert!(
        ALLOWED_SOURCE_KINDS.contains(&kind),
        "{}: source.kind {kind:?} is not one of the 5 discriminated-union kinds",
        path.display()
    );

    match kind {
        "lst_token" | "lst_inherited_copy" | "lst_corrected_ingest" => {
            for field in ["path", "sha256", "line", "record_key"] {
                assert!(
                    source.contains_key(field),
                    "{}: source.kind={kind} missing required field {field}",
                    path.display()
                );
            }
            let line = source.get("line").and_then(Value::as_u64).unwrap_or(0);
            assert!(line > 0, "{}: source.kind={kind} line must be a real (>0) line number, not a placeholder", path.display());
        }
        "web_second_source" => {
            for field in ["url", "fetched_at", "identity_match_basis"] {
                assert!(
                    source.contains_key(field),
                    "{}: source.kind=web_second_source missing required field {field}",
                    path.display()
                );
            }
            let url = source.get("url").and_then(Value::as_str).unwrap_or_default();
            assert!(
                url.contains("d20pfsrd.com") || url.contains("aonprd.com"),
                "{}: web_second_source url {url:?} is outside the allowed-domain list (decisions.md §11.5)",
                path.display()
            );
        }
        "same_book_fallback" => {
            assert!(
                source.contains_key("fallback_basis"),
                "{}: same_book_fallback missing fallback_basis",
                path.display()
            );
        }
        _ => unreachable!(),
    }
}

#[test]
fn monster_cache_has_all_46_real_monsters_with_chassis_data() {
    let records = load_all("monster");
    assert_eq!(records.len(), 46, "expected exactly the 46 real, corrected-roster Bestiary 1 monsters (MonsterId::ALL, decisions.md §11.6, raised from 41 by SD28-E16 subset 09)");

    let mut seen_names = HashSet::new();
    let mut slugs = BTreeSet::new();
    for (path, record) in &records {
        assert_shape_b_record(path, record);
        assert_eq!(record["completeness"], "chassis_only", "{}: monster chassis data is deliberately bounded (AC/HP/saves out of scope)", path.display());
        let data = &record["data"];
        let name = data["name"].as_str().unwrap().to_string();
        seen_names.insert(name);
        assert!(data["challenge_rating"].as_f64().unwrap() > 0.0, "{}: real CR must be positive", path.display());
        assert!(!data["size"].as_str().unwrap().is_empty(), "{}: missing size", path.display());
        // speed_ft may legitimately be 0 (e.g. Vargouille, a fly-only
        // creature whose real MOVE: token's walk speed is 0) -- assert
        // the field exists and is a non-negative real value, not that
        // it's positive.
        assert!(data["speed_ft"].as_u64().is_some(), "{}: missing speed_ft", path.display());
        assert!(!data["race_type"].as_str().unwrap().is_empty(), "{}: missing race_type", path.display());
        assert!(!data["source_page"].as_str().unwrap().is_empty(), "{}: missing source_page", path.display());
        assert_eq!(record["source"]["kind"], "lst_token");
        assert_eq!(record["source"]["path"], "pathfinder/paizo/roleplaying_game/bestiary/b1_races.lst");
        let id = data["id"].as_str().unwrap().to_string();
        assert!(id.starts_with("beastiary1:monster:"), "{}: id {id:?} must use the canonical beastiary1:monster:<slug> shape", path.display());
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        assert!(slugs.insert(stem.clone()), "{}: duplicate monster cache filename {stem}", path.display());
    }
    assert_eq!(seen_names.len(), 46, "every monster name must be unique");
}

#[test]
fn monster_cache_line_citations_match_the_real_corpus_for_spot_checked_entries() {
    // Real b1_races.lst first-column line numbers, independently
    // re-confirmed this cycle by direct grep of the live PCGen corpus
    // checkout (not transcribed blindly from a prior document) — see
    // this cycle's receipt.
    let expected_lines: &[(&str, u64)] = &[
        ("Ghoul", 200),
        ("Gnoll", 212),
        ("Ankheg", 18),
        ("Hell Hound", 230),
        ("Yellow Musk Creeper", 430),
        ("Rat Swarm", 334),
        ("Iron Cobra", 249),
        ("Dark Creeper", 89),
    ];
    let records: std::collections::HashMap<String, Value> = load_all("monster")
        .into_iter()
        .map(|(_, v)| (v["data"]["name"].as_str().unwrap().to_string(), v))
        .collect();
    for (name, line) in expected_lines {
        let record = records.get(*name).unwrap_or_else(|| panic!("missing monster record {name}"));
        assert_eq!(
            record["source"]["line"].as_u64(),
            Some(*line),
            "{name}: real b1_races.lst line citation mismatch"
        );
    }
}

#[test]
fn monster_cache_key_round_trips_through_the_real_monster_key_resolve_shape() {
    // The cache's own `data.id` field must match the exact key shape
    // `beastiary1::monster_key_resolve` accepts, so a consumer can
    // round-trip a cache record's id back into a live chassis-data
    // lookup.
    let records = load_all("monster");
    for (path, record) in &records {
        let id = record["data"]["id"].as_str().unwrap();
        let expected_prefix = "beastiary1:monster:";
        assert!(id.starts_with(expected_prefix), "{}: id {id:?} missing prefix", path.display());
    }
    // Spot check a few concrete ids resolve via the real function shape
    // documented in `beastiary1::monster_key_resolve`.
    let ids: HashSet<String> = records.iter().map(|(_, v)| v["data"]["id"].as_str().unwrap().to_string()).collect();
    for expected in [
        "beastiary1:monster:ghoul",
        "beastiary1:monster:goblin_dog",
        "beastiary1:monster:spider_swarm",
        "beastiary1:monster:cave_fisher",
        "beastiary1:monster:hell_hound",
    ] {
        assert!(ids.contains(expected), "expected id {expected:?} present in cache");
    }
}

/// Exhaustive corpus-vs-table field equality for all 46 monsters.
///
/// The two neighbouring monster tests above are deliberately partial:
/// `monster_cache_line_citations_match_the_real_corpus_for_spot_checked_entries`
/// and `monster_cache_key_round_trips_through_the_real_monster_key_resolve_shape`
/// both assert over a hand-picked handful. That left the actual
/// audited invariant — *every* field of *every* cached record equals
/// the shipped `MonsterStatBlock` — pinned nowhere, so a one-field
/// drift in either the Rust tables or the regenerated JSON cache could
/// land green.
///
/// The original cycle verified all 41 records by hand, three ways: the
/// cached JSON, the real PCGen row in
/// `pathfinder/paizo/roleplaying_game/bestiary/b1_races.lst` (whose
/// sha256 every record cites, and which matches the live checkout
/// byte-for-byte), and — for a 16-monster sample — the published
/// Bestiary values via aonprd/d20pfsrd. Zero discrepancies. SD28-E16
/// subset 09 (2026-08-07) added the 5 monsters that raise this from 41
/// to 46 (Lion, Ogre, Pegasus, Rust Monster, Shadow); each is cited to
/// its own `b1_races.lst` line and sha256 the same way, but was not
/// independently cross-checked against a published third-party
/// Bestiary source the way the original 16-monster sample was — that
/// cross-check is not repeated here and is a real, smaller gap this
/// note records rather than silently inheriting the stronger claim.
/// This test pins the field-equality result so it cannot silently
/// decay.
#[test]
fn every_monster_cache_record_matches_its_shipped_stat_block_field_for_field() {
    let records = load_all("monster");
    assert_eq!(records.len(), 46, "the real, corrected Bestiary 1 roster is 46 monsters");

    for (path, record) in &records {
        let data = &record["data"];
        let id = data["id"].as_str().unwrap_or_else(|| panic!("{}: missing data.id", path.display()));

        let block = monster_key_resolve(id, RuleSetId::Bestiary1)
            .unwrap_or_else(|| panic!("{}: id {id:?} does not resolve via monster_key_resolve", path.display()));

        assert_eq!(data["name"].as_str(), Some(block.name.as_str()), "{}: name", path.display());
        assert_eq!(
            data["challenge_rating"].as_f64(),
            Some(f64::from(block.challenge_rating)),
            "{}: challenge_rating",
            path.display()
        );
        assert_eq!(data["size"].as_str(), Some(block.size.as_str()), "{}: size", path.display());
        assert_eq!(data["speed_ft"].as_u64(), Some(u64::from(block.speed_ft)), "{}: speed_ft", path.display());
        assert_eq!(data["race_type"].as_str(), Some(block.race_type.as_str()), "{}: race_type", path.display());
        assert_eq!(
            data["race_subtype"].as_str(),
            block.race_subtype.as_deref(),
            "{}: race_subtype (JSON null <-> Rust None)",
            path.display()
        );
        assert_eq!(
            data["source_page"].as_str(),
            Some(block.source_page.as_str()),
            "{}: source_page",
            path.display()
        );

        let cached = data["natural_attacks"]
            .as_array()
            .unwrap_or_else(|| panic!("{}: natural_attacks must be an array", path.display()));
        assert_eq!(
            cached.len(),
            block.natural_attacks.len(),
            "{}: natural attack count",
            path.display()
        );
        // Order is load-bearing: it is the left-to-right order of the
        // `NATURALATTACKS:` token's `|`-separated entries on the real row.
        for (index, (json_attack, rust_attack)) in cached.iter().zip(&block.natural_attacks).enumerate() {
            assert_eq!(
                json_attack["name"].as_str(),
                Some(rust_attack.name.as_str()),
                "{}: natural_attacks[{index}].name",
                path.display()
            );
            assert_eq!(
                json_attack["damage_dice"].as_str(),
                Some(rust_attack.damage_dice.as_str()),
                "{}: natural_attacks[{index}].damage_dice",
                path.display()
            );
        }
    }
}

/// The 12 monsters whose natural-attack damage dice are not transcribed
/// from their own `b1_races.lst` row, and therefore carry per-field
/// provenance narrowing the record-level `lst_token` claim. See
/// `rules_tables::beastiary1::natural_attack_provenance`.
const GROUNDED_MONSTER_SLUGS: &[&str] = &[
    "ankheg",
    "assassin_vine",
    "boar",
    "cave_fisher",
    "centaur",
    "choker",
    "cockatrice",
    "crocodile",
    "vargouille",
    "wolf",
    "wolverine",
    "worg",
];

#[test]
fn field_provenance_is_present_on_exactly_the_twelve_grounded_monsters() {
    // A record-level `source.kind: "lst_token"` is truthful for the
    // chassis fields and the attack *names*, but would silently imply
    // the damage dice came from that line too. `field_provenance` is what
    // keeps the record honest -- if it vanishes, the cache starts
    // misattributing web-grounded values to a corpus line.
    let expected: BTreeSet<String> = GROUNDED_MONSTER_SLUGS.iter().map(|s| s.to_string()).collect();
    let mut actual = BTreeSet::new();
    for (path, record) in load_all("monster") {
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        if record.get("field_provenance").is_some() {
            actual.insert(stem);
        }
    }
    assert_eq!(
        actual, expected,
        "field_provenance must appear on exactly the 12 monsters whose attack dice were grounded outside their own row"
    );
}

#[test]
fn every_field_provenance_entry_points_at_a_real_attack_and_agrees_with_its_value() {
    for (path, record) in load_all("monster") {
        let Some(entries) = record.get("field_provenance") else { continue };
        let entries = entries
            .as_array()
            .unwrap_or_else(|| panic!("{}: field_provenance must be an array", path.display()));
        assert!(!entries.is_empty(), "{}: field_provenance must not be an empty array", path.display());

        let attacks = record["data"]["natural_attacks"].as_array().unwrap();
        for entry in entries {
            let field = entry["field"].as_str().unwrap_or_else(|| panic!("{}: provenance entry missing field", path.display()));
            // Parse `natural_attacks[<i>].damage_dice` and check the
            // cited index really holds the cited value.
            let index: usize = field
                .trim_start_matches("natural_attacks[")
                .split(']')
                .next()
                .and_then(|i| i.parse().ok())
                .unwrap_or_else(|| panic!("{}: unparseable provenance field {field:?}", path.display()));
            assert!(
                field.ends_with("].damage_dice"),
                "{}: provenance field {field:?} must target a damage_dice value",
                path.display()
            );
            let attack = attacks
                .get(index)
                .unwrap_or_else(|| panic!("{}: provenance cites natural_attacks[{index}], which does not exist", path.display()));
            assert_eq!(
                attack["damage_dice"].as_str(),
                entry["value"].as_str(),
                "{}: provenance value disagrees with natural_attacks[{index}].damage_dice",
                path.display()
            );
            assert!(
                !entry["corpus_name_token"].as_str().unwrap_or_default().is_empty(),
                "{}: provenance must record the real row token that names the attack",
                path.display()
            );
            assert!(
                !entry["published_melee_text"].as_str().unwrap_or_default().is_empty(),
                "{}: provenance must quote the published text the dice were read from",
                path.display()
            );

            let source = entry["source"].as_object().unwrap();
            let kind = source["kind"].as_str().unwrap();
            assert!(
                ALLOWED_SOURCE_KINDS.contains(&kind),
                "{}: field provenance kind {kind:?} is not one of the discriminated-union kinds",
                path.display()
            );
            match kind {
                "web_second_source" => {
                    let urls = source["urls"].as_array().unwrap_or_else(|| panic!("{}: web field provenance needs urls", path.display()));
                    assert!(
                        urls.len() >= 2,
                        "{}: {field} cites {} source(s) -- the grounding bar is at least two independent agreeing sources",
                        path.display(),
                        urls.len()
                    );
                    for url in urls {
                        let url = url.as_str().unwrap();
                        assert!(
                            url.contains("d20pfsrd.com") || url.contains("aonprd.com"),
                            "{}: url {url:?} is outside the allowed-domain list (decisions.md §11.5)",
                            path.display()
                        );
                    }
                    assert!(!source["identity_match_basis"].as_str().unwrap_or_default().is_empty());
                    assert!(!source["fetched_at"].as_str().unwrap_or_default().is_empty());
                }
                "lst_token" => {
                    // A real corpus recovery -- must cite a checkable line.
                    assert!(source["line"].as_u64().unwrap_or(0) > 0, "{}: {field} lst_token needs a real line", path.display());
                    for f in ["path", "sha256", "record_key"] {
                        assert!(source.contains_key(f), "{}: {field} lst_token missing {f}", path.display());
                    }
                }
                other => panic!("{}: unexpected field-provenance kind {other:?}", path.display()),
            }
        }
    }
}

#[test]
fn crocodile_tail_slap_cites_the_real_cross_file_corpus_token_it_was_recovered_from() {
    // The single genuine corpus recovery in this pass: `Crocodile ~ Tail
    // Slap` (b1_abilities_race.lst:248) carries a real inline
    // `NATURALATTACKS:...,*1,1d12`, unlike the dice-less generic markers
    // the other 11 monsters' references resolve to.
    let records: std::collections::HashMap<String, Value> = load_all("monster")
        .into_iter()
        .map(|(_, v)| (v["data"]["name"].as_str().unwrap().to_string(), v))
        .collect();
    let croc = records.get("Crocodile").expect("Crocodile record present");
    let entries = croc["field_provenance"].as_array().unwrap();
    let tail = entries
        .iter()
        .find(|e| e["value"] == "1d12")
        .expect("Crocodile tail slap provenance entry present");
    assert_eq!(tail["source"]["kind"], "lst_token", "the tail slap has a real corpus token; it must not cite as web_second_source");
    assert_eq!(tail["source"]["path"], "pathfinder/paizo/roleplaying_game/bestiary/b1_abilities_race.lst");
    assert_eq!(tail["source"]["line"].as_u64(), Some(248));
    assert_eq!(tail["source"]["record_key"], "Crocodile ~ Tail Slap");
}

#[test]
fn equipment_cache_has_exactly_the_real_4_records_at_the_real_100_percent_ceiling() {
    let records = load_all("equipment");
    assert_eq!(
        records.len(),
        4,
        "real Bestiary 1 equipment record count across b1_equip_general.lst (1) + b1_equip_arms_armor.lst (2) + b1_equip_magic_items.lst (1) — decisions.md §11.4's own correction: NOT the ~7 a prior SD-25 estimate assumed"
    );

    let mut has_description = 0;
    let mut slugs = BTreeSet::new();
    for (path, record) in &records {
        assert_shape_b_record(path, record);
        assert_eq!(record["completeness"], "full", "{}: all 4 real Bestiary 1 equipment records reach the full ceiling (description populated)", path.display());
        if !record["data"]["description"].is_null() {
            has_description += 1;
        }
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        assert!(slugs.insert(stem.clone()), "{}: duplicate equipment cache filename {stem}", path.display());
    }
    assert_eq!(has_description, 4, "real Bestiary 1 equipment description ceiling: 4/4 (100%), decisions.md §11.4");
}

#[test]
fn equipment_cache_uses_sprop_lst_token_for_the_three_register_a10_records() {
    // 3 of the 4 records source `description` from the corpus's
    // `SPROP:` ("Special Property") token, not `DESC:` — a real,
    // checkable LST token, just a different token name (decisions.md
    // §11.2's register A10 convention). These must cite honestly as
    // lst_token, never a fabricated web_second_source.
    let records: std::collections::HashMap<String, Value> = load_all("equipment")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();

    for key in ["Poison (Black Smear)", "Aklys", "Heartstone (Night Hag)"] {
        let record = records.get(key).unwrap_or_else(|| panic!("missing equipment record {key}"));
        assert_eq!(record["source"]["kind"], "lst_token", "{key}: SPROP:-sourced description must cite as lst_token");
        let line = record["source"]["line"].as_u64().unwrap_or(0);
        assert!(line > 0, "{key}: must resolve a real citation line");
    }
}

#[test]
fn equipment_cache_uses_web_second_source_for_rag_armor_with_an_allowed_domain() {
    // Rag Armor (Dark Creeper) has neither DESC: nor SPROP: in the real
    // LST corpus — the one genuine web-second-source record in this
    // book, carried forward from SD-25's own web pass (decisions.md
    // §11.3: never re-derive, never re-fetch, only dump the already-cited
    // value).
    let records: std::collections::HashMap<String, Value> = load_all("equipment")
        .into_iter()
        .map(|(_, v)| (v["data"]["key"].as_str().unwrap().to_string(), v))
        .collect();

    let record = records.get("Rag Armor (Dark Creeper)").expect("Rag Armor (Dark Creeper) present");
    assert_eq!(record["source"]["kind"], "web_second_source");
    let url = record["source"]["url"].as_str().unwrap();
    assert!(
        url.contains("d20pfsrd.com") || url.contains("aonprd.com"),
        "web_second_source url {url:?} outside the allowed-domain list"
    );
    assert!(!record["source"]["identity_match_basis"].as_str().unwrap().is_empty());
    assert_eq!(
        record["data"]["description"],
        "A dark creeper's multiple layers of filthy rags function as leather armor when worn by one of their kind."
    );
}

#[test]
fn equipment_cache_categories_map_to_the_real_three_corpus_files() {
    let records = load_all("equipment");
    let mut categories = BTreeSet::new();
    for (_, record) in &records {
        categories.insert(record["data"]["category"].as_str().unwrap().to_string());
    }
    let expected: BTreeSet<String> = ["General", "ArmsArmor", "MagicItems"].iter().map(|s| s.to_string()).collect();
    assert_eq!(categories, expected, "Bestiary 1 equipment covers exactly General/ArmsArmor/MagicItems — no equipmods file exists for this book");
}
